package EmployeeManagementSystem.service;
import EmployeeManagementSystem.entity.*; import EmployeeManagementSystem.repository.*; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class WorkforceSchedulingService { private final ShiftRepository shifts; private final ShiftAssignmentRepository assignments; private final EmployeeRepository employees; public WorkforceSchedulingService(ShiftRepository s,ShiftAssignmentRepository a,EmployeeRepository e){shifts=s;assignments=a;employees=e;}
 public ShiftAssignment get(Long id){return assignments.findById(id).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND,"Assignment not found"));}
 public String employeeUserId(Long id){Employee e=employees.findById(id).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND,"Employee not found"));return e.getRegisterEmployee()!=null?e.getRegisterEmployee().getUserId():e.getEmployeeProfile()==null?null:e.getEmployeeProfile().getUserId();}

 public List<Shift> shifts(){return shifts.findAll();} public Shift createShift(Shift s){if(s.getName()==null||s.getName().isBlank())throw new IllegalArgumentException("Shift name is required"); if(shifts.findByNameIgnoreCase(s.getName()).isPresent())throw new IllegalArgumentException("Shift name already exists"); return shifts.save(s);} public Shift updateShift(Long id,Shift x){Shift s=shifts.findById(id).orElseThrow(()->new IllegalArgumentException("Shift not found"));s.setName(x.getName());s.setStartTime(x.getStartTime());s.setEndTime(x.getEndTime());s.setStandardHours(x.getStandardHours());s.setDescription(x.getDescription());s.setOvernight(x.getOvernight());s.setActive(x.getActive());return shifts.save(s);}
 public void deleteShift(Long id){if(assignments.findAll().stream().anyMatch(a->a.getShift().getId().equals(id)))throw new IllegalArgumentException("Shift has assignments; deactivate it instead");shifts.deleteById(id);}
 public List<ShiftAssignment> my(String user){Employee e=employees.findByRegisterEmployee_UserId(user).or(()->employees.findByEmployeeProfile_UserId(user)).orElseThrow(()->new IllegalArgumentException("Employee not found for user " + user));return assignments.findByEmployee_IdOrderByShiftDateDesc(e.getId());} public List<ShiftAssignment> all(LocalDate from,LocalDate to){return assignments.findByShiftDateBetweenOrderByShiftDateAsc(from,to);} public ShiftAssignment assign(Long empId,Long shiftId,LocalDate date,String notes){Employee e=employees.findById(empId).orElseThrow(()->new IllegalArgumentException("Employee not found"));Shift s=shifts.findById(shiftId).orElseThrow(()->new IllegalArgumentException("Shift not found"));if(!Boolean.TRUE.equals(s.getActive()))throw new IllegalArgumentException("Shift is inactive");ShiftAssignment a=assignments.findByEmployee_IdAndShiftDate(empId,date).orElseGet(ShiftAssignment::new);a.setEmployee(e);a.setShift(s);a.setShiftDate(date);a.setNotes(notes);a.setStatus("SCHEDULED");return assignments.save(a);} public ShiftAssignment update(Long id,String status,Double overtime,String notes){ShiftAssignment a=assignments.findById(id).orElseThrow(()->new IllegalArgumentException("Assignment not found"));if(status!=null)a.setStatus(status);if(overtime!=null&&overtime>=0)a.setOvertimeHours(overtime);if(notes!=null)a.setNotes(notes);return assignments.save(a);} public void delete(Long id){assignments.deleteById(id);} public ShiftAssignment swap(Long id,String user,LocalDate newDate){ShiftAssignment a=assignments.findById(id).orElseThrow(()->new IllegalArgumentException("Assignment not found"));if(!a.getEmployee().getRegisterEmployee().getUserId().equals(user))throw new IllegalArgumentException("You can only request a swap for your own shift");a.setSwapStatus("REQUESTED");a.setNotes((a.getNotes()==null?"":a.getNotes()+" ")+"Swap requested for "+newDate);return assignments.save(a);}
}
